// 8 backends. Each request has a varying cost: it holds an active
// connection for `cost` future steps before it finishes (drains).
// 'load' = active connections on a backend at the moment of routing.
const N = 8, REQ = 10000;
function rng(seed){ return () => (seed = (seed*1103515245 + 12345) & 0x7fffffff) / 0x7fffffff; }
// imbalance = how far the busiest backend is above the average, in percent.
function imbalance(load){ const avg = load.reduce((a,b)=>a+b,0)/load.length; const max = Math.max(...load); return Math.round((max/avg - 1)*100); }

function simulate(pick){
  const rand = rng(42);
  const conns = new Array(N).fill(0);    // active connections right now
  const finish = new Array(N).fill(0).map(()=>[]); // pending finish times per backend
  const peak = new Array(N).fill(0);     // peak concurrency observed (the load we compare)
  let rrPtr = 0;
  for (let t=0;t<REQ;t++){
    // drain: close every connection whose cost has elapsed at this step
    for (let k=0;k<N;k++){
      const keep = finish[k].filter(f=>f>t);
      conns[k] = keep.length; finish[k] = keep;
    }
    // ~10% of requests are 10x heavier and hold the connection far longer
    const cost = rand() < 0.1 ? 10 : 1;
    const b = pick({conns, rand, advanceRR: ()=>{const p=rrPtr; rrPtr=(rrPtr+1)%N; return p;}});
    finish[b].push(t + cost);
    conns[b] = finish[b].length;
    if (conns[b] > peak[b]) peak[b] = conns[b];
  }
  return peak;
}

const roundRobin  = ({advanceRR}) => advanceRR();
const pureRandom  = ({conns, rand}) => Math.floor(rand()*conns.length);
const p2c = ({conns, rand}) => {
  const a = Math.floor(rand()*conns.length);
  let b = Math.floor(rand()*conns.length);
  if (b===a) b = (b+1)%conns.length;
  return conns[a] <= conns[b] ? a : b;   // route to the less-loaded of two
};

const rr = simulate(roundRobin);
const pr = simulate(pureRandom);
const tc = simulate(p2c);
console.log('round-robin   peak conns:', rr, 'imbalance:', imbalance(rr)+'%');
console.log('pure-random   peak conns:', pr, 'imbalance:', imbalance(pr)+'%');
console.log('power-of-two  peak conns:', tc, 'imbalance:', imbalance(tc)+'%');
console.log('=> power-of-two-choices keeps the busiest backend closest to the average.');
